"""
Test the arithmetic operations used in the verification.

The meta-model is written in Python, so the invariants follow the Python semantics
of the modulo and ``abs``. In particular, the remainder of the modulo takes
the sign of the divisor (``-7 % 3 == 2``). Mind that the native modulo in many
other languages, such as C#, C++, Go, Java and TypeScript, takes the sign of
the dividend instead (``-7 % 3 == -1``). Hence, the other SDKs follow the Python
semantics with dedicated helper functions, and test the very same cases.
"""


# This code has been automatically generated by aas-core-codegen.
# Do NOT edit or append.


import unittest


class TestArithmetic(unittest.TestCase):
    def test_modulo_0(self) -> None:
        # both operands positive
        self.assertEqual(1, 7 % 3)

    def test_modulo_1(self) -> None:
        # the remainder takes the sign of the positive divisor
        self.assertEqual(2, -7 % 3)

    def test_modulo_2(self) -> None:
        # the remainder takes the sign of the negative divisor
        self.assertEqual(-2, 7 % -3)

    def test_modulo_3(self) -> None:
        # both operands negative
        self.assertEqual(-1, -7 % -3)

    def test_modulo_4(self) -> None:
        # divisible, positive dividend
        self.assertEqual(0, 6 % 3)

    def test_modulo_5(self) -> None:
        # divisible, negative dividend
        self.assertEqual(0, -6 % 3)

    def test_modulo_6(self) -> None:
        # divisible, negative divisor
        self.assertEqual(0, 6 % -3)

    def test_modulo_7(self) -> None:
        # zero dividend, positive divisor
        self.assertEqual(0, 0 % 3)

    def test_modulo_8(self) -> None:
        # zero dividend, negative divisor
        self.assertEqual(0, 0 % -3)

    def test_modulo_9(self) -> None:
        # dividend smaller than the positive divisor
        self.assertEqual(2, 2 % 5)

    def test_modulo_10(self) -> None:
        # negative dividend smaller than the divisor
        self.assertEqual(3, -2 % 5)

    def test_modulo_11(self) -> None:
        # largest 64-bit integer, which is odd, by a positive divisor
        self.assertEqual(1, 9223372036854775807 % 2)

    def test_modulo_12(self) -> None:
        # largest 64-bit integer by a negative divisor
        self.assertEqual(-1, 9223372036854775807 % -2)

    def test_modulo_13(self) -> None:
        # smallest 64-bit integer by a positive divisor
        self.assertEqual(1, -9223372036854775808 % 3)

    def test_modulo_14(self) -> None:
        # smallest 64-bit integer by -1, which overflows with the native operator in some languages
        self.assertEqual(0, -9223372036854775808 % -1)

    def test_modulo_15(self) -> None:
        # smallest 64-bit integer by the largest one
        self.assertEqual(9223372036854775806, -9223372036854775808 % 9223372036854775807)

    def test_abs_of_int_0(self) -> None:
        self.assertEqual(5, abs(5))

    def test_abs_of_int_1(self) -> None:
        self.assertEqual(5, abs(-5))

    def test_abs_of_int_2(self) -> None:
        self.assertEqual(0, abs(0))

    def test_abs_of_int_3(self) -> None:
        self.assertEqual(9223372036854775807, abs(9223372036854775807))

    def test_abs_of_int_4(self) -> None:
        self.assertEqual(9223372036854775807, abs(-9223372036854775807))

    def test_abs_of_float_0(self) -> None:
        self.assertEqual(2.5, abs(2.5))

    def test_abs_of_float_1(self) -> None:
        self.assertEqual(2.5, abs(-2.5))

    def test_abs_of_float_2(self) -> None:
        self.assertEqual(0.0, abs(0.0))

    def test_abs_of_float_3(self) -> None:
        self.assertEqual(0.0, abs(-0.0))

    def test_abs_of_float_4(self) -> None:
        self.assertEqual(1.7976931348623157e+308, abs(-1.7976931348623157e+308))


if __name__ == "__main__":
    unittest.main()


